type Seq = number & { readonly __seq: unique symbol };
const window = new Map<Seq, Envelope>();
let expected = 1 as Seq;
export function accept(env: Envelope, deliver: (e: Envelope) => void) {
  window.set(env.seq, env);                    // duplicates policy: keep last
  while (window.has(expected)) {
    deliver(window.get(expected)!);            // ordered run
    window.delete(expected);
    expected = (expected + 1) as Seq;
  }
  rearmGap(expected);                          // timeout policy: skip the hole
}
